#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
자동 발행 고치기  (더블클릭 한 번)

하는 일
  1) .github/workflows/ 안에 워크플로 3개를 제대로 넣는다
     (구글 드라이브가 점(.)으로 시작하는 폴더를 못 만들어서 빠져 있던 것)
  2) post.py 를 새 버전으로 바꾼다
     - 깃허브 예약 실행이 2~5시간씩 밀리는 문제 대응
     - 한 번 깨어나면 그날 남은 시간까지 지키고 있다가 제때 올린다
  3) 깃허브에 올린다 → 올라가는 즉시 오늘 치 발행이 시작된다

이 파일은 저장소 폴더(=post.py, queue.csv 가 있는 폴더) 안에 두고 실행하세요.
"""

import base64, os, subprocess, sys

ROOT = os.path.dirname(os.path.abspath(__file__))

PAYLOAD = {'.github/workflows/daily-post.yml': '',
 '.github/workflows/monthly-refresh.yml': '',
 '.github/workflows/weekly-content.yml': '',
 'post.py': ''}


def run(*a, **kw):
    return subprocess.run(a, cwd=ROOT, text=True, capture_output=True, **kw)


def main():
    print("찐한국 자동 발행 - 수리 스크립트")
    print("폴더:", ROOT)
    print()

    if not os.path.exists(os.path.join(ROOT, "queue.csv")):
        print("!! 이 스크립트를 queue.csv 가 있는 폴더에 두고 실행하세요.")
        input("\n엔터를 누르면 닫힙니다...")
        return

    print("1) 파일 넣는 중")
    for rel, b64 in PAYLOAD.items():
        path = os.path.join(ROOT, *rel.split("/"))
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "wb") as f:
            f.write(base64.b64decode(b64))
        print("   -", rel)

    # 잘못된 자리에 있던 워크플로 정리
    stray = os.path.join(ROOT, "workflows")
    if os.path.isdir(stray):
        for n in os.listdir(stray):
            try:
                os.remove(os.path.join(stray, n))
            except OSError:
                pass
        try:
            os.rmdir(stray)
            print("   - 잘못된 위치의 workflows/ 폴더 정리")
        except OSError:
            pass

    print()
    print("2) 깃허브에 올리는 중")
    run("git", "config", "user.name", "wonbi")
    run("git", "config", "user.email", "wonbi@users.noreply.github.com")
    run("git", "add", "-A")
    c = run("git", "commit", "-m", "자동 발행 안정화: 워크플로 보강 + watch 모드")
    if c.returncode != 0 and "nothing to commit" in (c.stdout + c.stderr):
        print("   변경 없음 - 이미 최신입니다")
    p = run("git", "push")
    if p.returncode != 0:
        run("git", "pull", "--rebase", "--autostash")
        p = run("git", "push")
    if p.returncode == 0:
        print("   OK 올라갔습니다")
        print()
        print("   잠시 뒤 아래에서 '자동 발행' 이 도는 걸 볼 수 있습니다:")
        print("   https://github.com/wonbi/insta-threads-auto/actions")
    else:
        print("   !! 실패")
        print(p.stderr.strip()[:800])
        print()
        print("   로그인 창이 떴는지 확인해 보세요 (Alt+Tab)")

    input("\n엔터를 누르면 닫힙니다...")


if __name__ == "__main__":
    main()
